const ease = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
let shake = 0;
function puff(p) {
  const d = WP.fx.dust.find(d => d.t >= 1) || WP.fx.dust[0];
  d.t = 0; d.sp.visible = true; d.sp.position.copy(p);
}
function updateWaypoint(dt, t) {
  if (!WP.freeze) WP.T = WP.active ? Math.min(WP.TMAX, WP.T + dt) : Math.max(0, WP.T - dt * 1.5);
  const T = WP.T, G = smooth(3.45, 3.95, T), F = WP.fx;
  WP.spin += dt * 0.5 * G;
  const pos = wpPosition, q = wpRotation, spinQ = wpSpinRotation;
  for (const b of WP.blocks) {
    const start = 0.55 + b.order * 0.12, lt = Math.min(1, Math.max(0, (T - start) / 0.95)), e = ease(lt);
    const ax = b.a[0], az = b.a[2];
    let tx = ax, tz = az, ty = b.a[1];
    if (b.float === 2 || b.float === 3) {
      const ang = WP.spin * (b.float === 3 ? 1.6 : 1), c = Math.cos(ang), s2 = Math.sin(ang);
      tx = ax * c - az * s2; tz = ax * s2 + az * c;
    }
    if (b.float) ty += Math.sin(t * 1.7 + b.phase) * 0.07 * G;
    pos.set(b.r[0] + (tx - b.r[0]) * e, b.r[1] + (ty - b.r[1]) * e + Math.sin(Math.PI * lt) * b.arc, b.r[2] + (tz - b.r[2]) * e);
    // before lifting off the heap shudders
    const quake = T > 0.05 && lt === 0 && WP.active ? smooth(0.05, 0.5, T) : 0;
    if (quake) pos.x += Math.sin(t * 47 + b.phase) * 0.025, pos.z += Math.cos(t * 41 + b.phase) * 0.025;
    q.copy(b.qr).slerp(b.qa, ease(lt));
    if (b.float === 3) q.multiply(spinQ.setFromAxisAngle(wpAxis, t * 0.9 * G));
    if (b.float === 2) q.premultiply(spinQ.setFromAxisAngle(wpAxis, WP.spin));
    b.mesh.position.copy(pos); b.mesh.quaternion.copy(q);
    if (lt >= 1 && !b.landed) { b.landed = true; if (!b.float && dt > 0) { puff(new V3(pos.x, b.a[1] - b.h / 2 + 0.1, pos.z)); shake = Math.max(shake, 0.06); } }
    if (lt <= 0) b.landed = false;
    if (b.glow) b.glow.opacity = G * (0.85 + 0.15 * Math.sin(t * 3 + b.phase)) + (WP.active ? 0 : 0.18 + 0.12 * Math.sin(t * 2.2));
  }
  F.circle.material.opacity = smooth(0.0, 0.5, T) * (0.8 + 0.15 * Math.sin(t * 2));
  F.circle.rotation.z = t * 0.15;
  F.seams[0].children[0].material.opacity = G * (0.8 + 0.2 * Math.sin(t * 2.6));
  F.ribbonMat.uniforms.uOpacity.value = G;
  F.ribbons[0].rotation.y = t * 0.9; F.ribbons[1].rotation.y = -t * 0.7;
  const arr = F.points.geometry.attributes.position.array;
  F.motes.forEach((m, k) => { m.y = (m.y + dt * m.v) % 3.6; const a = m.a + t * 0.3; arr[k * 3] = Math.cos(a) * m.r; arr[k * 3 + 1] = m.y; arr[k * 3 + 2] = Math.sin(a) * m.r; });
  F.points.geometry.attributes.position.needsUpdate = true;
  F.moteMat.opacity = Math.max(G, smooth(0.0, 0.5, T) * 0.5);
  F.hint.material.opacity = WP.active ? 0 : 0.3 + 0.2 * Math.sin(t * 2.2);
  for (const d of F.dust) {
    if (d.t >= 1) continue;
    d.t = Math.min(1, d.t + dt / 0.7); d.sp.scale.setScalar(0.5 + d.t * 1.8); d.sp.material.opacity = 0.75 * (1 - d.t); d.sp.position.y += dt * 0.4;
    if (d.t >= 1) d.sp.visible = false;
  }
}


function placeCoastPlants(){
  const place=(mesh,items,scale)=>{
    const m=new THREE.Matrix4(),q=new THREE.Quaternion(),c=new THREE.Color();
    items.forEach((it,i)=>{q.setFromEuler(new THREE.Euler(it.rx||0,it.ry||0,0,'YXZ'));m.compose(new V3(it.x,it.y,it.z),q,scale(it));mesh.setMatrixAt(i,m);mesh.setColorAt(i,it.c?c.set(it.c):c.setRGB(it.k,it.k,it.k*.97));});mesh.instanceMatrix.needsUpdate=true;return mesh;
  };
  if(woodParts.length){const wood=new THREE.Mesh(mergeGeometries(woodParts),paint({vertexColors:true,shade:[.55,.48,.46],mid:[.78,.69,.60]}));wood.castShadow=wood.receiveShadow=true;scene.add(wood);}
  if(coconutParts.length)scene.add(new THREE.Mesh(mergeGeometries(coconutParts),paint({vertexColors:true})));
  for(const young of[false,true]){
    const items=frondItems.filter(f=>f.young===young);if(!items.length)continue;const geo=young?gamePalmFrond(2.3,1.4,.45,.95):gamePalmFrond(4.2,1.1,1.9,1.5);
    const mat=paint({map:palmFrondTexture(),alphaTest:.45,side:THREE.DoubleSide,shade:[.58,.68,.62],mid:[.58,.68,.62],band:[-5,-5],sway:[.05,0]});
    const mesh=place(new THREE.InstancedMesh(geo,mat,items.length),items,it=>new V3(it.s*1.35,it.s*1.35,it.s*1.35));mesh.customDepthMaterial=new THREE.MeshDepthMaterial({depthPacking:THREE.RGBADepthPacking,map:palmFrondTexture(),alphaTest:.45});mesh.castShadow=mesh.receiveShadow=true;scene.add(mesh);
  }
  const leafMat=shrub=>paint({vertexColors:true,map:branchletTexture(shrub),alphaTest:.45,side:THREE.DoubleSide,shade:[.60,.70,.72],mid:[.60,.70,.72],band:[-5,-5],sway:[shrub?.02:.016,shrub?0:1.2]});
  const leafDepth=shrub=>new THREE.MeshDepthMaterial({depthPacking:THREE.RGBADepthPacking,map:branchletTexture(shrub),alphaTest:.45});
  const trunks=place(new THREE.InstancedMesh(animeTrunk(),paint({vertexColors:true,shade:[.62,.62,.70],mid:[.62,.62,.70],band:[-5,-5]}),treeItems.length),treeItems,it=>new V3(it.s,it.s,it.s));trunks.castShadow=trunks.receiveShadow=true;scene.add(trunks);
  for(const[seed,v]of [[3,0],[5,1],[9,2]]){
    // Fuller crowns, as in the concepts' canopy: wider than the game's default, on the same trunks and colliders.
    const items=treeItems.filter(t=>t.v===v).map(t=>({...t,y:t.y+3.5*t.s}));if(!items.length)continue;
    const mesh=place(new THREE.InstancedMesh(animeFoliage(seed,false),leafMat(false),items.length),items,it=>new V3(2.5*it.s,1.7*it.s,2.25*it.s));mesh.customDepthMaterial=leafDepth(false);mesh.castShadow=mesh.receiveShadow=true;scene.add(mesh);
  }
  for(const[seed,v]of[[11,0],[13,1],[19,2]]){
    const items=shrubItems.filter(t=>t.v===v);if(!items.length)continue;
    const mesh=place(new THREE.InstancedMesh(animeFoliage(seed,true),leafMat(true),items.length),items,it=>new V3(it.sx,it.sy,it.sz));mesh.customDepthMaterial=leafDepth(true);mesh.castShadow=mesh.receiveShadow=true;scene.add(mesh);
  }
  for(const[type,items,geo]of[['grass',grassItems,meadowGrass()],['flowers',flowerItems,wildflower()]]){
    const mesh=place(new THREE.InstancedMesh(geo,paint({vertexColors:true,side:THREE.DoubleSide,shade:[.6,.72,.68],mid:[.6,.72,.68],band:[-5,-5],sway:[.12,0]}),items.length),items,it=>new V3(it.s,it.s,it.s));mesh.receiveShadow=true;scene.add(mesh);
  }
}

